inline Json effective_profile(const Json& binding){const auto p=verify(binding);const auto config=read(p);
 if(binding.at("sha256")!="d2b5cfdc6be023c715fe402a7124ccd1977f5956b8d9fa74466643a575dbd0e0"&&binding.at("sha256")!="9a6639f89f78e0f448d7629c71848c181a32e72bc020a5a4e2186d14b2fd8474")throw std::runtime_error("unsupported current Runtime profile hash");
 const auto& capture=config.at("capture");const auto& touch=config.at("touch");const auto& scheduler=config.at("scheduler");const auto& game=config.at("game");
 if(capture.at("width")!=1280||capture.at("height")!=720||capture.at("source_rotation")!=1||capture.at("image_format")!="rgb888"||capture.at("row_order")!="top-down"||touch.at("max_contacts")!=5||scheduler.at("max_plans")!=128||scheduler.at("max_steps")!=16||scheduler.at("horizon_ms")!=350||scheduler.at("evidence_max_age_ms")!=100||game.at("lead_ms")!=35||game.at("uncertainty_ms")!=30||game.at("enabled_types")!=Json::array({"tap","hold","drag","flick"}))throw std::runtime_error("profile differs from effective offline Runtime constants");
 return {{"width",1280},{"height",720},{"rotation",1},{"rgb_stride",3840},{"max_contacts",5},{"enabled_type_bits",15},{"lead_ns",35000000},{"uncertainty_ns",30000000},{"max_plans",128},{"max_steps",16},{"horizon_ns",350000000},{"evidence_max_age_ns",100000000},{"capture","offline_memory_stub"},{"touch","ReplayBackend"},{"device_endpoints",0}};
}
inline Json producer(const fs::path& manifest,const std::string& run_id,const fs::path& executable,const std::string& mode,const std::string& scene,int requested,const fs::path& report,const Json& process){
 const auto campaign=read(manifest);if(campaign.at("schema")!="pas.current-rails-campaign-freeze.v2"||campaign.at("configuration")!="Release"||campaign.at("platform")!="windows-x64"||requested!=2560)throw std::runtime_error("bound producer campaign contract");
 const auto source=source_closure(campaign);(void)source;Json roles=Json::object();for(const auto& b:campaign.at("bindings")){const auto role=b.at("role").get<std::string>();if(roles.contains(role))throw std::runtime_error("duplicate campaign role");verify(b);roles[role]=b;}
 if(verify(roles.at("candidate_binary"))!=fs::canonical(executable))throw std::runtime_error("running binary differs from frozen candidate");
 const Json* planned=nullptr;for(const auto& entry:campaign.at("planned_runs"))if(entry.at("run_id")==run_id){if(planned)throw std::runtime_error("duplicate planned run");planned=&entry;}
 if(!planned||planned->at("mode")!=mode||planned->at("scene")!=scene||fs::weakly_canonical(planned->at("report_path").get<std::string>())!=fs::weakly_canonical(report))throw std::runtime_error("producer run identity differs from freeze");
 if(process.at("pid").get<std::uint64_t>()==0||process.at("creation_filetime").get<std::uint64_t>()==0||process.at("run_start_ns").get<std::int64_t>()<=0)throw std::runtime_error("producer process identity");
 return {{"schema","pas.current-rails-run-provenance.v1"},{"campaign_id",campaign.at("id")},{"campaign_sha256",evidence::sha256(manifest)},{"source_commit",campaign.at("source_commit")},{"run_id",run_id},{"mode",mode},{"scene",scene},{"requested",requested},{"report_path",fs::weakly_canonical(report).string()},{"candidate_binary_sha256",roles.at("candidate_binary").at("sha256")},{"source_manifest_sha256",roles.at("source_manifest").at("sha256")},{"profile_sha256",roles.at("profile").at("sha256")},{"environment_sha256",roles.at("environment").at("sha256")},{"cost_protocol_sha256",roles.at("cost_protocol").at("sha256")},{"process",process},{"effective_profile",effective_profile(roles.at("profile"))}};
}
